CREATE TYPE "ShipmentStatus" AS ENUM ('PENDING','READY_TO_SHIP','SHIPPED','IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','FAILED','RETURNED');
CREATE TYPE "ReturnStatus" AS ENUM ('REQUESTED','APPROVED','REJECTED','IN_TRANSIT','RECEIVED','COMPLETED','CANCELLED');
CREATE TABLE "ShippingRule" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"countryCode" CHAR(2) NOT NULL DEFAULT 'IN',"pricingMode" "PricingMode","minSubtotalPaise" INTEGER NOT NULL DEFAULT 0,"maxSubtotalPaise" INTEGER,"shippingPaise" INTEGER NOT NULL,"priority" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ShippingRule_pkey" PRIMARY KEY("id"),CONSTRAINT "ShippingRule_amounts_check" CHECK ("minSubtotalPaise">=0 AND ("maxSubtotalPaise" IS NULL OR "maxSubtotalPaise">="minSubtotalPaise") AND "shippingPaise">=0 AND "priority">=0));
CREATE INDEX "ShippingRule_countryCode_pricingMode_isActive_priority_idx" ON "ShippingRule"("countryCode","pricingMode","isActive","priority");
CREATE TABLE "Shipment" ("id" UUID NOT NULL,"orderId" UUID NOT NULL,"carrierName" TEXT NOT NULL,"trackingNumber" TEXT,"trackingUrl" TEXT,"status" "ShipmentStatus" NOT NULL DEFAULT 'PENDING',"shippedAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Shipment_pkey" PRIMARY KEY("id"),CONSTRAINT "Shipment_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Shipment_orderId_key" ON "Shipment"("orderId");CREATE INDEX "Shipment_orderId_idx" ON "Shipment"("orderId");CREATE INDEX "Shipment_trackingNumber_idx" ON "Shipment"("trackingNumber");CREATE INDEX "Shipment_status_idx" ON "Shipment"("status");CREATE INDEX "Shipment_createdAt_idx" ON "Shipment"("createdAt");
CREATE TABLE "ReturnRequest" ("id" UUID NOT NULL,"orderId" UUID NOT NULL,"userId" UUID NOT NULL,"status" "ReturnStatus" NOT NULL DEFAULT 'REQUESTED',"reason" TEXT NOT NULL,"customerNote" TEXT,"adminNote" TEXT,"reviewedByAdminId" UUID,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ReturnRequest_pkey" PRIMARY KEY("id"),CONSTRAINT "ReturnRequest_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "ReturnRequest_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "ReturnRequest_reviewedByAdminId_fkey" FOREIGN KEY("reviewedByAdminId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "ReturnRequest_orderId_idx" ON "ReturnRequest"("orderId");CREATE INDEX "ReturnRequest_userId_createdAt_idx" ON "ReturnRequest"("userId","createdAt");CREATE INDEX "ReturnRequest_status_createdAt_idx" ON "ReturnRequest"("status","createdAt");CREATE INDEX "ReturnRequest_reviewedByAdminId_idx" ON "ReturnRequest"("reviewedByAdminId");
CREATE TABLE "ReturnItem" ("id" UUID NOT NULL,"returnRequestId" UUID NOT NULL,"orderItemId" UUID NOT NULL,"quantity" INTEGER NOT NULL,"restockedQuantity" INTEGER NOT NULL DEFAULT 0,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ReturnItem_pkey" PRIMARY KEY("id"),CONSTRAINT "ReturnItem_quantities_check" CHECK ("quantity">0 AND "restockedQuantity">=0 AND "restockedQuantity"<="quantity"),CONSTRAINT "ReturnItem_returnRequestId_fkey" FOREIGN KEY("returnRequestId") REFERENCES "ReturnRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ReturnItem_orderItemId_fkey" FOREIGN KEY("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ReturnItem_returnRequestId_orderItemId_key" ON "ReturnItem"("returnRequestId","orderItemId");CREATE INDEX "ReturnItem_returnRequestId_idx" ON "ReturnItem"("returnRequestId");CREATE INDEX "ReturnItem_orderItemId_idx" ON "ReturnItem"("orderItemId");
